import json

records = ['{"done": 3}', '{"done": true}', '[]', '{broken']
for text in records:
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        print('invalid')
        continue
    if isinstance(value, dict) and type(value.get('done')) is int and value['done'] >= 0:
        print(value['done'])
    else:
        print('invalid')
